// === Tab: mySketch ===
const CYCLE  = 150;
const NUM = 6;
const VERT_XZ_NUM = 20;
let renderer;
let sh;
let lapse = 0;    // mouse timer

function setup() {
	renderer = createCanvas(1112, 834,WEBGL);
	noStroke();
	fill(255);

	//shader
	sh = createShader(vert,frag);
	this.shader(sh);
	sh.setUniform("u_resolution", [width,height]);
	sh.setUniform("u_lightDir", [1,0.8,-0.5]);
	noStroke();
	colorMode(HSB, 255);
	pixelDensity(2);
}

function draw() {
	background(10);
	//scale(1, -1);  // uncomment this line when saving an image or thumbnail
	orbitControl();
	rotateX(PI/10);
	let frameRad = (frameCount/CYCLE)*TWO_PI ;
	let frameRad2 = (frameCount/(CYCLE/2))*TWO_PI ;

	let startY = -height/4-height/8*sin(frameRad);
	let yStep = 10;
	let yNum = Math.floor((height-startY)/yStep);
	let angleStep = (sin(frameRad)+0.8)*0.05;
	let pipeRadius = 20;
	let moveRadiusBase = 100;


	for(i = 0; i < NUM; i++){
		let angle = frameRad + (TWO_PI/NUM)*i;
		let y = startY;
		let pipeGeo = new p5.Geometry(VERT_XZ_NUM-1,yNum-1);
		//setCol(sh,"u_col",'00FF00');
	  if (i == 0) setCol(sh,"u_col",'#FF5555');
	  if (i == 1) setCol(sh,"u_col",'#55FF55');
	  if (i == 2) setCol(sh,"u_col",'#5555FF');
	  if (i == 3) setCol(sh,"u_col",'#FFFF55');
	  if (i == 4) setCol(sh,"u_col",'#55FFFF');
	  if (i == 5) setCol(sh,"u_col",'#FF55FF');

		//createPipe
		for(let yi = 0; yi < yNum; yi++)
		{
			//calculate center position
			let moveRadius = moveRadiusBase * (1 + 0.2*sin(frameRad2 + yi/10 ));
			let x = cos(angle)*moveRadius;
			let z = sin(angle)*moveRadius;

			//calculate vertex
			for(let vi = 0; vi < VERT_XZ_NUM; vi ++)
			{
				let vr = vi*TWO_PI/VERT_XZ_NUM;
				let vx = x + cos(vr)*pipeRadius;
				let vz = z + sin(vr)*pipeRadius;
				let index = yi*VERT_XZ_NUM + vi;
				pipeGeo.vertices[index] = createVector(vx,y,vz);
			}
			angle += angleStep;
			y += yStep;
		}
		drawGeometry(pipeGeo);
	}
}


function setCol(shader,uniformName,colStr)
{
	let col = color(colStr);
	let colArray = col._array;
	colArray.pop();
	shader.setUniform(uniformName,colArray);
}



function drawGeometry(_geo,_id = 'custom',_renderer = renderer)
{
	_geo.computeFaces();
	_geo.computeNormals();
	_renderer.createBuffers(_id, _geo);
	_renderer.drawBuffers(_id);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

// === Tab: shader ===
var vert = `

		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      vec3 pos = aPosition;  
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;


var frag = `

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform vec3 u_lightDir;
uniform vec3 u_col;
uniform mat3 uNormalMatrix;

//attributes, in
varying vec4 var_centerGlPosition;
varying vec3 var_vertNormal;




float random (in vec2 st) {
   	highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}

float grid(vec2 uv){
	uv *= 10.;
  uv = fract(uv);
  float v = uv.x >= 0. && uv.x < 0.1 || uv.y >= 0. && uv.y < 0.1 ? 1. : 0.;
  return v;
}

float gridGra(in vec2 uv , float gridNum){
    float scale = gridNum;
    uv *= scale;
    uv = fract(uv);
    float o = abs(uv.y + -0.5)*2.;
		o *= abs(uv.x + -0.5)*2.;
    return o;
}

void main() {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
		st.x *= u_resolution.x/u_resolution.y;

		vec2 centerPos = var_centerGlPosition.xy/var_centerGlPosition.w;//スクリーン変換
		centerPos = (centerPos + 1.0)*.5*2.;//gl_FragCoordと座標を合わせる pixelDensityによって係数が変化する
		centerPos.x *= u_resolution.x/u_resolution.y;//gl_FragCoordと座標を合わせる
		vec3 vertNormal = normalize(uNormalMatrix * var_vertNormal);
    float dot = dot(vertNormal,normalize(u_lightDir));
    dot = (dot *.5) + .5;


    float noise1 = noise((st-centerPos)*500.);
		float noise2 = noise((st-centerPos)*1000.);
		float tone = step(noise1,dot);
		vec3 col = u_col * tone + (u_col-0.8) * (1.-tone);
		col += noise2*.15;
    vec3 color = vec3(0.);
    color = vec3(st.x,st.y,abs(sin(u_time)));

	gl_FragColor = vec4(col,1.0);
}

`;

